function Aircraft = GroundChargeEquivalentCircuit(Aircraft, ChrgTime, PowerStrategy, TimeStep)
% Ground-charge FAST's battery using a cached Simscape Battery ECM profile.
%
% The profile is generated by the R2026b Battery Equivalent Circuit and
% Charger blocks.  The selected model is temperature-independent, has no RC
% polarization states, and has aging disabled, so SOC is its only dynamic
% battery state.  A single monotonic CC-CV trajectory can therefore be time
% shifted to represent any feasible initial SOC without re-compiling
% Simscape during every optimizer evaluation.

if nargin < 3 || isempty(PowerStrategy)
    PowerStrategy = Aircraft.Specs.Battery.Charging;
end
if nargin < 4 || isempty(TimeStep)
    TimeStep = 1;
end
if ~isscalar(ChrgTime) || ~isfinite(ChrgTime) || ChrgTime < 0
    error("BatteryPkg:GroundChargeEquivalentCircuit:InvalidChargeTime", ...
        "ChrgTime must be a finite nonnegative scalar number of seconds.");
end
if ~isscalar(TimeStep) || ~isfinite(TimeStep) || TimeStep <= 0
    error("BatteryPkg:GroundChargeEquivalentCircuit:InvalidTimeStep", ...
        "TimeStep must be a finite positive scalar number of seconds.");
end
if ~isscalar(PowerStrategy) || ~isfinite(PowerStrategy) || PowerStrategy == 0
    error("BatteryPkg:GroundChargeEquivalentCircuit:InvalidPower", ...
        "The Simscape equivalent-circuit charger requires scalar nonzero power.");
end

Batt = find(Aircraft.Specs.Propulsion.PropArch.SrcType == 0, 1);
if isempty(Batt)
    error("BatteryPkg:GroundChargeEquivalentCircuit:NoBatterySource", ...
        "The propulsion architecture does not contain a battery source.");
end
SOCBeg = Aircraft.Mission.History.SI.Power.SOC(end, Batt);
if ~isscalar(SOCBeg) || ~isfinite(SOCBeg)
    error("BatteryPkg:GroundChargeEquivalentCircuit:InvalidInitialSOC", ...
        "The final mission battery SOC must be a finite scalar.");
end

Series = Aircraft.Specs.Power.Battery.SerCells;
Parallel = Aircraft.Specs.Power.Battery.ParCells;
CellCapacity_Ah = Aircraft.Specs.Battery.CapCell;
PackCapacity_Ah = CellCapacity_Ah * Parallel;
NominalPackVoltage_V = Aircraft.Specs.Battery.NomVolCell * Series;
MaxPackVoltage_V = Aircraft.Specs.Battery.MaxExtVolCell * Series;
MaxChargeCurrent_A = Aircraft.Specs.Battery.MaxAllowCRate * PackCapacity_Ah;
ChargeCurrent_A = min(abs(PowerStrategy) / NominalPackVoltage_V, ...
    MaxChargeCurrent_A);
ChargeCutoffCurrent_A = 0.02 * PackCapacity_Ah;

SOCBreakpoints = [0.01, 0.05, 0.10:0.05:1.00];
DischargedCapacity_Ah = (1 - SOCBreakpoints) * CellCapacity_Ah;
PolarizationVoltage_V = 0.0011;
DischargeCurveSlope = 0.29732;
CellOCV_V = Aircraft.Specs.Battery.MaxExtVolCell + ...
    Aircraft.Specs.Battery.ExpVol .* exp( ...
    -Aircraft.Specs.Battery.ExpCap .* DischargedCapacity_Ah) - ...
    PolarizationVoltage_V .* DischargedCapacity_Ah ./ SOCBreakpoints - ...
    DischargeCurveSlope .* DischargedCapacity_Ah;
% FAST's charging branch uses a charge-direction polarization resistance.
ChargeResistanceCell_Ohm = Aircraft.Specs.Battery.IntResist + ...
    PolarizationVoltage_V ./ (1.1 - SOCBreakpoints);
PackOCV_V = CellOCV_V * Series;
PackResistance_Ohm = ChargeResistanceCell_Ohm * Series / Parallel;

CacheKey = sprintf("S%d_P%d_Q%.12g_P%.12g_V%.12g_R%.12g_A%.12g_" + ...
    "B%.12g_I%.12g", Series, Parallel, CellCapacity_Ah, ...
    abs(PowerStrategy), MaxPackVoltage_V, Aircraft.Specs.Battery.IntResist, ...
    Aircraft.Specs.Battery.ExpVol, Aircraft.Specs.Battery.ExpCap, ...
    ChargeCurrent_A);
Profile = GetChargeProfile(CacheKey);

SOCBegFraction = min(max(SOCBeg / 100, Profile.SOC(1)), 1);
if SOCBegFraction >= Profile.SOC(end)
    StartProfileTime_s = Profile.Time_s(end);
else
    [UniqueSOC, UniqueIdx] = unique(Profile.SOC, "first");
    StartProfileTime_s = interp1(UniqueSOC, Profile.Time_s(UniqueIdx), ...
        SOCBegFraction, "linear");
end

HistoryTime_s = (0:TimeStep:ChrgTime)';
if isempty(HistoryTime_s) || HistoryTime_s(end) < ChrgTime
    HistoryTime_s(end + 1, 1) = ChrgTime;
end
ProfileQueryTime_s = min(StartProfileTime_s + HistoryTime_s, ...
    Profile.Time_s(end));
SOC = interp1(Profile.Time_s, Profile.SOC, ProfileQueryTime_s, ...
    "linear", Profile.SOC(end));
Voltage = interp1(Profile.Time_s, Profile.Voltage_V, ProfileQueryTime_s, ...
    "linear", Profile.Voltage_V(end));
BatteryCurrent_A = interp1(Profile.Time_s, Profile.Current_A, ...
    ProfileQueryTime_s, "linear", 0);
SOC = min(max(SOC, 0), 1);

Aircraft.Mission.History.SI.Power.ChargedAC.CtrlPtsTimeStep = TimeStep;
Aircraft.Mission.History.SI.Power.ChargedAC.Time_s = HistoryTime_s;
Aircraft.Mission.History.SI.Power.ChargedAC.SOCEnd = 100 * SOC(end);
Aircraft.Mission.History.SI.Power.ChargedAC.SOC = 100 * SOC;
Aircraft.Mission.History.SI.Power.ChargedAC.Voltage = Voltage;
Aircraft.Mission.History.SI.Power.ChargedAC.VolCell = Voltage / Series;
Aircraft.Mission.History.SI.Power.ChargedAC.Current = -BatteryCurrent_A;
Aircraft.Mission.History.SI.Power.ChargedAC.P_in = Voltage .* BatteryCurrent_A;
Aircraft.Mission.History.SI.Power.ChargedAC.Capacity = ...
    PackCapacity_Ah .* SOC;
Aircraft.Mission.History.SI.Power.ChargedAC.C_rate = ...
    -BatteryCurrent_A ./ PackCapacity_Ah;
Aircraft.Mission.History.SI.Power.ChargedAC.Model = ...
    "Simscape Battery Equivalent Circuit CC-CV";

    function ProfileOut = GetChargeProfile(Key)
        persistent ProfileCache
        if isempty(ProfileCache)
            ProfileCache = containers.Map("KeyType", "char", "ValueType", "any");
        end
        if isKey(ProfileCache, Key)
            ProfileOut = ProfileCache(Key);
            return
        end

        ProjectRoot = fileparts(fileparts(mfilename("fullpath")));
        ModelFile = fullfile(ProjectRoot, "FASTBatteryEquivalentCircuit.slx");
        if ~isfile(ModelFile)
            BuildFASTBatteryEquivalentCircuitModel(ModelFile);
        end
        ModelName = "FASTBatteryEquivalentCircuit";
        % The installed pack reaches its CC-CV current cutoff in well under
        % 90 minutes from the 20% operational floor.  Avoid simulating a
        % long post-charge open-circuit tail, which can force unnecessarily
        % small Simscape solver steps around the charger switching event.
        ProfileStopTime_s = 90 * 60;
        Input = Simulink.SimulationInput(ModelName);
        Input = Input.setVariable("FAST_PackCapacity_Ah", PackCapacity_Ah);
        Input = Input.setVariable("FAST_SOCBreakpoints", SOCBreakpoints);
        Input = Input.setVariable("FAST_PackOCV_V", PackOCV_V);
        Input = Input.setVariable("FAST_PackResistance_Ohm", PackResistance_Ohm);
        Input = Input.setVariable("FAST_InitialSOC", ...
            Aircraft.Specs.Battery.MinSOC / 100);
        Input = Input.setVariable("FAST_ChargeCurrent_A", ChargeCurrent_A);
        Input = Input.setVariable("FAST_MaxPackVoltage_V", MaxPackVoltage_V);
        Input = Input.setVariable("FAST_ChargeCutoffCurrent_A", ...
            ChargeCutoffCurrent_A);
        Input = Input.setModelParameter("StopTime", string(ProfileStopTime_s));
        Input = Input.setModelParameter("MaxStep", "5");
        Output = sim(Input);
        Log = Output.simlog_FASTBatteryEquivalentCircuit.Battery;

        ProfileOut.Time_s = Log.stateOfCharge.series.time;
        ProfileOut.SOC = Log.stateOfCharge.series.values("1");
        ProfileOut.Voltage_V = Log.batteryVoltage.series.values("V");
        ProfileOut.Current_A = Log.batteryCurrent.series.values("A");
        ProfileOut.SOC = min(max(ProfileOut.SOC(:), 0), 1);
        ProfileOut.Time_s = ProfileOut.Time_s(:);
        VoltageTime_s = Log.batteryVoltage.series.time;
        CurrentTime_s = Log.batteryCurrent.series.time;
        ProfileOut.Voltage_V = interp1( ...
            VoltageTime_s(:), ProfileOut.Voltage_V(:), ...
            ProfileOut.Time_s, "linear", "extrap");
        ProfileOut.Current_A = interp1( ...
            CurrentTime_s(:), ProfileOut.Current_A(:), ...
            ProfileOut.Time_s, "linear", "extrap");

        % The ideal charger opens its circuit at the current cutoff.  The
        % battery can then drift slightly through self-discharge during the
        % unused remainder of the profile simulation, which would make SOC
        % nonmonotonic and invalidate the time-shift lookup.  Retain only
        % the charging trajectory through its first maximum SOC.
        [~, PeakIdx] = max(ProfileOut.SOC);
        ProfileOut.Time_s = ProfileOut.Time_s(1:PeakIdx);
        ProfileOut.SOC = ProfileOut.SOC(1:PeakIdx);
        ProfileOut.Voltage_V = ProfileOut.Voltage_V(1:PeakIdx);
        ProfileOut.Current_A = ProfileOut.Current_A(1:PeakIdx);

        if ProfileOut.SOC(end) <= Aircraft.Specs.Battery.MinSOC / 100
            error("BatteryPkg:GroundChargeEquivalentCircuit:ProfileIncomplete", ...
                "Simscape CC-CV profile did not charge above %.3f%% after " + ...
                "%.1f minutes.", 100 * ProfileOut.SOC(end), ...
                ProfileStopTime_s / 60);
        end
        ProfileCache(Key) = ProfileOut;
    end
end
